// Salah guide generated by scripts/convert-salah-guide.mjs.
import fs from "node:fs/promises";
import path from "node:path";
import { cache } from "react";

export type SalahBlock = {
  type: "heading" | "text" | "verse" | "hadith" | "list";
  text: string;
  reference?: string;
};

export type SalahTopic = { id: string; question: string; intro: string; steps: boolean; blocks: SalahBlock[] };
export type SalahCategory = { id: string; title: string; subtitle: string; topics: SalahTopic[] };
export type SalahGuide = { title: string; subtitle: string; categories: SalahCategory[] };

export const getSalahGuide = cache(
  async (): Promise<SalahGuide> =>
    JSON.parse(await fs.readFile(path.join(process.cwd(), "data/salah-guide/guide.json"), "utf8")),
);

/** All topics in reading order, with their category. */
export async function getSalahTopics() {
  const guide = await getSalahGuide();
  return guide.categories.flatMap((category) => category.topics.map((topic) => ({ category, topic })));
}
